LIMIT 1;

MATCH (s:PlantItem {tag: 'C-39-1'}), (t:PlantItem {tag: 'P-39-3'})
RETURN s.tag AS from_tag, t.tag AS to_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*1..]->(t)
         WHERE all(n IN nodes(p) WHERE coalesce(n.tag, '') <> 'CHV-39-2')
       } AS can_flow

MATCH p = shortestPath(
  (s:PlantItem {tag: "TK-274-2"})-[:send_to*]->(t:PlantItem {tag: "P-373-3"})
)
RETURN [n IN nodes(p)
        WHERE n:Equipment OR n:OperatedValve OR n:BallValve OR n:GlobeValve OR n:CheckValve
        | n.tag] AS equipment_and_valve_tags_in_order;

